+#[cfg(feature = "standard-unicode-escaping")]
+struct UnescapeUnicodeCharIterator<'a> {
+    iter: Chars<'a>,
+    buffer: String,
+}
+
+#[cfg(feature = "standard-unicode-escaping")]
+impl<'a> UnescapeUnicodeCharIterator<'a> {
+    fn new(string: &'a str) -> Self {
