+            self.iter.next()?
+        } else {
+            self.buffer.remove(0)
+        };
+        match c {
+            '\\' => match self.iter.next() {
+                Some('u') => {
+                    self.buffer.push('u');
+                    for _ in 0..4 {
+                        if let Some(c) = self.iter.next() {
